from pathlib import Path
import json,hashlib,datetime,collections,gzip
p=Path(__file__).resolve().parent
regraw=(p/'strength-registration.json').read_bytes();reg=json.loads(regraw);seal=hashlib.sha256(regraw).hexdigest()
for r in reg['files']:assert hashlib.sha256((p/r['path']).read_bytes()).hexdigest()==r['sha256'],r['path']
statuses={h:json.loads((p/f'confirmation-{h}/status.json').read_text())for h in ['local','puffalo']}
assert all(r['complete']and not r['errors']and not r['liveWorkerPids']for r in statuses.values()),'Both frozen shards must finish before score inspection'
assert sum(r['fights']for r in statuses.values())==18144
assert json.loads((p/'preaggregate-quality-audit.json').read_text())['passed']
assert json.loads((p/'fresh-cold-parity.json').read_text())['passed']
cases={(r['board'],r['game']):r for r in json.loads((p/'cases.json').read_text())};cov={r['board']:r for r in json.loads((p/'strength-family-covariates.json').read_text())};pairs={};rawsha={};coverage=collections.Counter();cpu=collections.defaultdict(lambda:collections.defaultdict(float));accepted_calls=0
for host in ['local','puffalo']:
 for file in sorted((p/f'confirmation-{host}').glob('worker-*.jsonl.gz')):
  raw=file.read_bytes();rawsha[str(file.relative_to(p))]=hashlib.sha256(raw).hexdigest()
  for line in gzip.decompress(raw).splitlines():
   row=json.loads(line);key=(row['board'],row['game']);job=cases[key]
   assert row['registrationSha256']==seal and row['assignedHost']==host==cov[row['board']]['host']
   assert row['seed']==job['seed']and row['inputSha256']==job['expectedInputSha256']
   team=2 if(row['game']<2)==(row['game']%2==0)else 1;assert row['team']==team
   assert row['winner']in ['green','red','draw']
   half=1 if row['winner']=='draw'else 2*int(row['winner']==('green'if team==2 else'red'));assert row['score']*2==half
   assert row['quality']['rejected']==0 and all(n['modelErrors']==0 and n['missingStart']==0 for n in row['quality']['neural'])
   assert all(w.get('deadlineFallbacks',0)==0 and w.get('circuitSkipped',0)==0 and w.get('circuitWaitArbitrations',0)==0 for w in row['quality']['work'])
   pair=pairs.setdefault(key,{});assert row['mode']not in pair;pair[row['mode']]={**row,'half':half}
   cpu[host][row['mode']]+=row['fightCpuMicros']/1000
   if row['mode']=='accepted':accepted_calls+=row['acceptedModelCalls']
   if row['mode']=='mixture':coverage['mixtureRoots']+=row['mixtureRoots']
assert len(pairs)==6048 and set(pairs)==set(cases)
assert all(set(r)=={'stock','mixture','accepted'}for r in pairs.values())
assert accepted_calls>0 and coverage['mixtureRoots']>0
families=[];totals=collections.Counter();transitions=collections.Counter();changedfamilies=0;changedcases=0
for board in range(1512):
 deltas={m:0 for m in ['stock','accepted']};changed=False
 for game in range(4):
  r=pairs[(board,game)]
  for m,row in r.items():totals[m]+=row['half']
  for m in deltas:deltas[m]+=r['mixture']['half']-r[m]['half']
  diff=r['mixture']['traceSha256']!=r['stock']['traceSha256'];changed|=diff;changedcases+=diff
  transitions[f"{r['stock']['score']}->{r['mixture']['score']}"]+=1
 changedfamilies+=changed;families.append({**cov[board],'halfPointDeltas':deltas,'changedTrace':changed})
def bootstrap(values,seed):
 state=seed;out=[];n=len(values)
 for _ in range(20000):
  total=0
  for i in range(n):
   state^=(state<<13)&0xffffffff;state&=0xffffffff;state^=state>>17;state&=0xffffffff;state^=(state<<5)&0xffffffff;state&=0xffffffff;total+=values[state%n]
  out.append(total)
 out.sort();return [out[500]/(n*8),out[19500]/(n*8)]
primary_values=[r['halfPointDeltas']['stock']for r in families];primary={'meanDelta':sum(primary_values)/(1512*8),'wholeFamily95CI':bootstrap(primary_values,1746189201)}
secondary={m:{'meanDelta':sum(r['halfPointDeltas'][m]for r in families)/(1512*8),'wholeFamily95CI':bootstrap([r['halfPointDeltas'][m]for r in families],1746189202+i),'descriptiveOnly':True}for i,m in enumerate(['accepted'])}
by={}
for field in ['map','ownDoctrine','opponentDoctrine','style','host']:
 by[field]={}
 for value in sorted({r[field]for r in families},key=str):
  subset=[r for r in families if r[field]==value];by[field][str(value)]={'families':len(subset),'meanDelta':sum(r['halfPointDeltas']['stock']for r in subset)/(len(subset)*8)}
gates={'minimumHalfPointGain':primary['meanDelta']>=.005,'positiveLower95':primary['wholeFamily95CI'][0]>0,'mapNoncatastrophic':min(v['meanDelta']for v in by['map'].values())>=-.01,'ownDoctrineNoncatastrophic':min(v['meanDelta']for v in by['ownDoctrine'].values())>=-.01,'opponentStyleNoncatastrophic':min(v['meanDelta']for v in by['style'].values())>=-.01,'changedFamiliesAtLeast24':changedfamilies>=24}
result={'id':reg['id'],'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'complete':True,'families':1512,'fights':18144,'primary':primary,'secondary':secondary,'armScores':{k:v/(6048*2)for k,v in totals.items()},'armIntegerHalfPoints':dict(totals),'by':by,'gates':gates,'strengthGatePassed':all(gates.values()),'changedCases':changedcases,'changedFamilies':changedfamilies,'primaryOutcomeTransitions':dict(transitions),'forecastCoverage':dict(coverage),'acceptedReferenceCalls':accepted_calls,'concurrentDescriptiveCpuMsOnly':{h:dict(v)for h,v in cpu.items()},'serialTimingQualified':False,'freshConfirmationOpened':True,'defaultChanged':False,'registrationSha256':seal,'hostStatuses':statuses,'rawSha256':rawsha,'scope':'Independent naturally barrel-conditioned legal draft families with full adopted terrain-aware v11 combat and real paid public native Setup. Different host families cannot identify a hardware strength effect. Independent confirmation does not automatically promote or deploy; separate preselected v11 real-clock cost must also pass.'}
(p/'confirmation-analysis.json').write_text(json.dumps(result,indent=2)+'\n');(p/'confirmation-family-deltas.json').write_text(json.dumps(families,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items()if k not in ['rawSha256','hostStatuses']},indent=2))

import assert from "node:assert/strict";
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import {gunzipSync}from"node:zlib";
const p=import.meta.dir,read=(f:string)=>JSON.parse(readFileSync(`${p}/${f}`,"utf8"));
const analysis=read("confirmation-analysis.json"),rawRegistration=readFileSync(`${p}/strength-registration.json`);
assert.equal(analysis.registrationSha256,createHash("sha256").update(rawRegistration).digest("hex"));
const expected=new Map<string,any>(read("cases.json").map((r:any)=>[`${r.board}/${r.game}`,r]));
const cov=new Map<number,any>(read("strength-family-covariates.json").map((r:any)=>[r.board,r]));
const pairs=new Map<string,Map<string,any>>();let count=0;
for(const host of ["local","puffalo"]){
 const status=read(`confirmation-${host}/status.json`);assert(status.complete&&!status.errors.length&&!status.liveWorkerPids.length);
 for(const file of readdirSync(`${p}/confirmation-${host}`).filter(f=>/^worker-\d+\.jsonl\.gz$/.test(f))){
  for(const line of gunzipSync(readFileSync(`${p}/confirmation-${host}/${file}`)).toString().trim().split("\n").filter(Boolean)){
   const r=JSON.parse(line),key=`${r.board}/${r.game}`,job=expected.get(key);assert(job);assert.equal(r.assignedHost,host);assert.equal(cov.get(r.board).host,host);
   assert.equal(r.registrationSha256,analysis.registrationSha256);assert.equal(r.inputSha256,job.expectedInputSha256);assert.equal(r.seed,job.seed);
   const team=(r.game<2)===(r.game%2===0)?2:1;assert.equal(r.team,team);assert(["green","red","draw"].includes(r.winner));
   const half=r.winner==="draw"?1:Number(r.winner===(team===2?"green":"red"))*2;assert.equal(half,r.score*2);
   assert.equal(r.quality.rejected,0);for(const n of r.quality.neural){assert.equal(n.modelErrors,0);assert.equal(n.missingStart,0);}
   for(const w of r.quality.work){assert.equal(w.deadlineFallbacks??0,0);assert.equal(w.circuitSkipped??0,0);assert.equal(w.circuitWaitArbitrations??0,0);}
   const pair=pairs.get(key)??new Map();assert(!pair.has(r.mode));pair.set(r.mode,{...r,half});pairs.set(key,pair);count++;
  }
 }
}
assert.equal(count,18144);assert.equal(pairs.size,6048);
const totals:Record<string,number>={stock:0,mixture:0,accepted:0},families:any[]=[];let changedCases=0,changedFamilies=0;
for(let board=0;board<1512;board++){
 const deltas:Record<string,number>={stock:0,accepted:0};let changed=false;
 for(let game=0;game<4;game++){
  const r=pairs.get(`${board}/${game}`)!;assert.deepEqual([...r.keys()].sort(),["accepted","mixture","stock"]);
  for(const [mode,row]of r)totals[mode]+=row.half;
  for(const mode of Object.keys(deltas))deltas[mode]+=r.get("mixture").half-r.get(mode).half;
  const diff=r.get("mixture").traceSha256!==r.get("stock").traceSha256;changed||=diff;changedCases+=Number(diff);
 }
 changedFamilies+=Number(changed);families.push({...cov.get(board),deltas});
}
assert.deepEqual(totals,analysis.armIntegerHalfPoints);assert.equal(changedCases,analysis.changedCases);assert.equal(changedFamilies,analysis.changedFamilies);
const sample=(values:number[],seed:number)=>{
 let x=seed;const sums:number[]=[];
 for(let b=0;b<20000;b++){let sum=0;for(let i=0;i<1512;i++){x^=x<<13;x^=x>>>17;x^=x<<5;sum+=values[(x>>>0)%1512];}sums.push(sum);}
 sums.sort((a,b)=>a-b);return [sums[500]/12096,sums[19500]/12096];
};
const primary=families.map(f=>f.deltas.stock),mean=primary.reduce((a,b)=>a+b,0)/12096,interval=sample(primary,1746189201);
assert.equal(mean,analysis.primary.meanDelta);assert.deepEqual(interval,analysis.primary.wholeFamily95CI);
for(const [i,mode]of ["accepted"].entries()){
 const values=families.map(f=>f.deltas[mode]);assert.equal(values.reduce((a,b)=>a+b,0)/12096,analysis.secondary[mode].meanDelta);assert.deepEqual(sample(values,1746189202+i),analysis.secondary[mode].wholeFamily95CI);
}
const safety=(field:string)=>{
 const groups=new Map<string,number[]>();for(const f of families){const key=String(f[field]),values=groups.get(key)??[];values.push(f.deltas.stock);groups.set(key,values);}
 return [...groups.values()].every(v=>v.reduce((a,b)=>a+b,0)/(v.length*8)>=-.01);
};
const gates={minimumHalfPointGain:mean>=.005,positiveLower95:interval[0]>0,mapNoncatastrophic:safety("map"),ownDoctrineNoncatastrophic:safety("ownDoctrine"),opponentStyleNoncatastrophic:safety("style"),changedFamiliesAtLeast24:changedFamilies>=24};
assert.deepEqual(gates,analysis.gates);assert.equal(Object.values(gates).every(Boolean),analysis.strengthGatePassed);
const result={passed:true,at:new Date().toISOString(),independentIntegerRawOutcomesAndWholeFamilyBootstrapExact:true,resamplesPerContrast:20000,primaryMean:mean,primaryCI:interval,gates,strengthGatePassed:Object.values(gates).every(Boolean),analysisSha256:createHash("sha256").update(readFileSync(`${p}/confirmation-analysis.json`)).digest("hex")};
writeFileSync(`${p}/independent-confirmation-verification.json`,JSON.stringify(result,null,2)+"\n");console.log(JSON.stringify(result));
